// ── Dijkstra's Algorithm — O((V+E) log V) ─────────────────────────────
// graph: adjacency list { node: [[neighbor, weight], ...] }
//
// For a real implementation, replace the array-sort priority queue
// with a proper binary min-heap (e.g. a third-party 'heap' package).
// The logic is identical; only the PQ operations change.

function dijkstra(graph, source) {
  const dist = {};
  const prev = {};
  const settled = new Set();

  // Initialise all distances to Infinity
  for (const node of Object.keys(graph)) {
    dist[node] = Infinity;
    prev[node] = null;
  }
  dist[source] = 0;

  // Min-heap: array of [distance, vertex], always sorted ascending
  const pq = [[0, source]];

  while (pq.length > 0) {
    // Extract minimum — O(n log n) with sort; O(log n) with real heap
    pq.sort((a, b) => a[0] - b[0]);
    const [d, u] = pq.shift();

    // Stale entry: this vertex was already settled with a shorter dist
    if (settled.has(u)) continue;
    settled.add(u);

    // Relax all outgoing edges from u
    for (const [v, w] of (graph[u] || [])) {
      const candidate = d + w;
      if (candidate < dist[v]) {
        dist[v] = candidate;
        prev[v] = u;
        pq.push([candidate, v]); // lazy push — stale entries handled above
      }
    }
  }

  return { dist, prev };
}

// Reconstruct the actual path from source to any target
function reconstructPath(prev, target) {
  const path = [];
  let cur = target;
  while (cur !== null) {
    path.unshift(cur);
    cur = prev[cur];
  }
  return path;
}

// ── Worked example ────────────────────────────────────────────────────
const graph = {
  S: [["A", 4], ["B", 2]],
  A: [["T", 3]],
  B: [["A", 1], ["T", 5]],
  T: []
};

const { dist, prev } = dijkstra(graph, "S");
console.log(dist);
// { S: 0, A: 3, B: 2, T: 6 }
// Trace: S→B (cost 2), B→A (cost 2+1=3), A→T (cost 3+3=6)

console.log(reconstructPath(prev, "T"));
// ["S", "B", "A", "T"]

// ── Bellman-Ford — O(V * E), handles negative weights ────────────────
// vertices: array of vertex labels (e.g. ["A","B","C"])
// edges: array of [u, v, weight] triples

function bellmanFord(vertices, edges, source) {
  const dist = {};
  const prev = {};

  // Initialise
  for (const v of vertices) {
    dist[v] = Infinity;
    prev[v] = null;
  }
  dist[source] = 0;

  // V-1 relaxation rounds
  for (let round = 0; round < vertices.length - 1; round++) {
    let anyUpdate = false; // early termination optimisation
    for (const [u, v, w] of edges) {
      if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        prev[v] = u;
        anyUpdate = true;
      }
    }
    // If no update happened, shortest paths are already optimal — stop early
    if (!anyUpdate) break;
  }

  // V-th round: detect negative cycles
  for (const [u, v, w] of edges) {
    if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
      return { negativeCycle: true, dist: null, prev: null };
    }
  }

  return { negativeCycle: false, dist, prev };
}

// ── Example: negative edge but NO negative cycle ──────────────────────
const vertices = ["A", "B", "C", "D"];
const edges = [
  ["A", "B",  4],
  ["A", "C",  2],
  ["C", "B", -1],   // shortcut: A→C→B costs 2+(-1) = 1  (beats A→B = 4)
  ["B", "D",  3],
  ["C", "D",  6]
];

const result = bellmanFord(vertices, edges, "A");
console.log(result.negativeCycle); // false
console.log(result.dist);
// { A: 0, B: 1, C: 2, D: 4 }
// Path to D: A→C→B→D (cost 2-1+3=4), beats A→C→D (2+6=8)

// ── Example: with a negative cycle ───────────────────────────────────
const vertsCyc = ["X", "Y", "Z"];
const edgesCyc = [
  ["X", "Y",  1],
  ["Y", "Z", -3],
  ["Z", "X",  1]   // cycle X→Y→Z→X total weight = 1-3+1 = -1
];
const res2 = bellmanFord(vertsCyc, edgesCyc, "X");
console.log(res2.negativeCycle); // true — shortest paths undefined
